-- Phase 3.2: destination content, publishing workflow, history, and JSON migration.
with source as (select * from jsonb_to_recordset($d$[
{"ord":1,"slug":"egypt","name":"Egypt","subtitle":"The Crown Jewel of History","description":"Experience more than 7,000 years of living history. From the timeless majesty of the Pyramids to the pristine shores of the Red Sea and the historic waters of the Nile, our Egyptian operations are the beating heart of Flash Group.","highlights":["Serenity Nile Cruises","True Beach Resort - Marsa Alam","1920s Boutique Hotel - Cairo","Tulipe Kitesurfing Hub"],"image":"/images/egypt-bg.jpg","heroImage":"/images/egypt-hospitality-bg.jpg","icon":"Compass","code":"EG","region":"North Africa","eyebrow":"THE HEART OF THE EMPIRE","heroTitle":"Mystical","accent":"EGYPT","heroSubtitle":"We do not just organize your journey; we own every aspect of it. Unparalleled destinations crafted for the elite."},
{"ord":2,"slug":"uae","name":"United Arab Emirates","subtitle":"Where Luxury Knows No Bounds","description":"Our UAE division caters to the most discerning travelers. We seamlessly blend ultra-modern luxury with authentic Arabian hospitality, offering exclusive access to VIP services, premium mobility, and bespoke experiences in Dubai and beyond.","highlights":["VIP Chauffeur Services","Luxury Desert Safaris","Exclusive Hotel Partnerships","Corporate Retreats"],"image":"/images/uae-bg.jpg","heroImage":"/images/uae-hero.jpg","icon":"Building","code":"AE","region":"Middle East","eyebrow":"5-STAR CORPORATE & LEISURE","heroTitle":"Luxury","accent":"UAE","heroSubtitle":"Where luxury comes directly to you. Elevating corporate travel, VIP mobility, and elite leisure across the Emirates."},
{"ord":3,"slug":"zanzibar","name":"Zanzibar","subtitle":"The Pearl of the Indian Ocean","description":"Escape to a tropical paradise where white sandy beaches meet rich cultural heritage. Our Zanzibar operations deliver untouched nature paired with Flash Group’s signature 5-star standard of comfort and safety.","highlights":["Premium Beachfront Resorts","Spice Tour Experiences","Diving & Water Sports","Private Yacht Charters"],"image":"/images/zanzibar-bg.jpg","heroImage":"/images/zanzibar-hero.jpg","icon":"Sun","code":"TZ","region":"East Africa","eyebrow":"EXOTIC ESCAPES & WILDLIFE","heroTitle":"Exotic","accent":"ZANZIBAR","heroSubtitle":"Africa, the land of the wildlife. Enjoy the best of both worlds with pristine beaches and unforgettable Savanna Safaris."},
{"ord":4,"slug":"italy","name":"Italy","subtitle":"The Essence of Sophistication","description":"Catering to the sophisticated European market, we bring our legacy of luxury to the Mediterranean. From the sweet life of Sicily to the glamour of San Remo and Sardinia, we operate 7 exclusive premium properties.","highlights":["7 Premium Italian Hotels","Sicily & Sardinia Excursions","Olive Oil Farm Tours","Bespoke Mediterranean Hospitality"],"image":"/images/italy-bg.jpg","heroImage":"/images/italy-hero.jpg","icon":"MapPin","code":"IT","region":"Southern Europe","eyebrow":"DOLCE FAR NIENTE","heroTitle":"Classic","accent":"ITALY","heroSubtitle":"With a warm and friendly nature, a Dolce Vita lifestyle, and a passion for fine cuisine. Unparalleled Mediterranean luxury."},
{"ord":5,"slug":"morocco","name":"Morocco","subtitle":"The Gateway to Africa","description":"Immerse yourself in vibrant colors, rich traditions, and unparalleled North African luxury. From the bustling souks of Marrakech to the majestic Atlas Mountains and the serene Sahara, our Moroccan operations offer an unforgettable blend of culture and elegance.","highlights":["Marrakech Luxury Riads","Atlas Mountains Excursions","Sahara Desert Camps","Authentic Culinary Tours"],"image":"","heroImage":"","icon":"Map","code":"MA","region":"North Africa","eyebrow":"THE GATEWAY TO AFRICA","heroTitle":"Enchanting","accent":"Morocco","heroSubtitle":"Immerse yourself in vibrant colors, rich traditions, and unparalleled North African luxury."}
]$d$::jsonb) as x(ord int,slug text,name text,subtitle text,description text,highlights jsonb,image text,"heroImage" text,icon text,code text,region text,eyebrow text,"heroTitle" text,accent text,"heroSubtitle" text)), prepared as(select x.*,jsonb_build_object('name',name,'slug',slug,'subtitle',subtitle,'description',description,'iconKey',icon,'sortOrder',ord*10,'hero',jsonb_build_object('eyebrow',eyebrow,'title',"heroTitle",'accentTitle',accent,'subtitle',"heroSubtitle",'image',jsonb_build_object('assetId',null,'url',"heroImage",'alt',name)),'country',jsonb_build_object('code',code,'region',region,'officeLabel','Flash Group '||name),'highlights',(select jsonb_agg(jsonb_build_object('id','highlight-'||n,'title',v)) from jsonb_array_elements_text(highlights) with ordinality h(v,n)),'gallery',case when image='' then '[]'::jsonb else jsonb_build_array(jsonb_build_object('id','gallery-1','image',jsonb_build_object('assetId',null,'url',image,'alt',name),'caption',subtitle)) end) content from source x)
insert into public.content_entries(id,content_type,slug,title,locale,status,sort_order,draft_data,published_data,published_at) select ('33000000-0000-4000-8000-'||lpad(ord::text,12,'0'))::uuid,'destination',slug,name,'en','published',ord*10,content,content,now() from prepared on conflict(content_type,locale,slug) do nothing;
insert into public.seo_entries(content_entry_id,locale,draft_data,published_data,published_at) select id,locale,jsonb_build_object('title',title||' | Flash Group','description',left(draft_data->>'description',170),'keywords',jsonb_build_array(title,'luxury travel','Flash Group'),'canonicalUrl','/destinations/'||slug,'openGraph',jsonb_build_object('title',title||' | Flash Group','description',left(draft_data->>'description',220),'image',draft_data#>>'{hero,image,url}')),jsonb_build_object('title',title||' | Flash Group','description',left(draft_data->>'description',170),'keywords',jsonb_build_array(title,'luxury travel','Flash Group'),'canonicalUrl','/destinations/'||slug,'openGraph',jsonb_build_object('title',title||' | Flash Group','description',left(draft_data->>'description',220),'image',draft_data#>>'{hero,image,url}')),now() from public.content_entries where content_type='destination' on conflict(content_entry_id,locale) where content_entry_id is not null do nothing;
insert into public.content_revisions(resource_type,resource_id,version,snapshot,event) select 'destination',e.id,1,jsonb_build_object('content',e.draft_data,'seo',s.draft_data),'published' from public.content_entries e join public.seo_entries s on s.content_entry_id=e.id where e.content_type='destination' on conflict do nothing;

create function public.cms_create_destination(requested_title text,requested_slug text,requested_locale text,content_data jsonb,seo_data jsonb) returns uuid language plpgsql set search_path='' as $$ declare rid uuid; ord int; begin
if not public.current_user_has_permission('content.create') or not public.current_user_has_permission('seo.edit') then raise exception 'You do not have permission to create destinations.' using errcode='42501'; end if;
select coalesce(max(sort_order),0)+10 into ord from public.content_entries where content_type='destination' and locale=requested_locale; content_data:=content_data||jsonb_build_object('name',requested_title,'slug',requested_slug,'sortOrder',ord);
insert into public.content_entries(content_type,slug,title,locale,sort_order,draft_data) values('destination',requested_slug,requested_title,requested_locale,ord,content_data) returning id into rid; insert into public.seo_entries(content_entry_id,locale,draft_data) values(rid,requested_locale,seo_data); insert into public.content_revisions(resource_type,resource_id,version,snapshot,event,created_by) values('destination',rid,1,jsonb_build_object('content',content_data,'seo',seo_data),'draft_saved',(select auth.uid())); return rid; end $$;
create function public.cms_save_destination_draft(requested_destination_id uuid,expected_lock_version int,content_data jsonb,seo_data jsonb,create_revision boolean default false) returns jsonb language plpgsql set search_path='' as $$ declare saved public.content_entries; v int; asset jsonb; begin
if not public.current_user_has_permission('content.edit') or not public.current_user_has_permission('seo.edit') then raise exception 'You do not have permission to edit destinations.' using errcode='42501'; end if;
if exists(select 1 from public.content_entries c where c.content_type='destination' and c.id<>requested_destination_id and (c.slug=content_data->>'slug' or c.draft_data->>'slug'=content_data->>'slug')) then raise exception 'A destination already uses this slug.' using errcode='23505'; end if;
update public.content_entries set draft_data=content_data,title=case when status='draft' then content_data->>'name' else title end,slug=case when status='draft' then content_data->>'slug' else slug end,sort_order=case when status='draft' then (content_data->>'sortOrder')::int else sort_order end,updated_by=(select auth.uid()) where id=requested_destination_id and content_type='destination' and lock_version=expected_lock_version returning * into saved; if saved.id is null then raise exception 'This destination was changed in another session.' using errcode='40001'; end if;
update public.seo_entries set draft_data=seo_data where content_entry_id=saved.id; delete from public.media_usages where content_entry_id=saved.id; for asset in select * from jsonb_array_elements(jsonb_build_array(content_data->'hero'->'image')||coalesce(jsonb_path_query_array(content_data,'$.gallery[*].image'),'[]')) loop if nullif(asset->>'assetId','') is not null then insert into public.media_usages(asset_id,content_entry_id,field_key) values((asset->>'assetId')::uuid,saved.id,'destination.image.'||(asset->>'assetId')) on conflict do nothing; end if; end loop;
if create_revision then select coalesce(max(version),0)+1 into v from public.content_revisions where resource_type='destination' and resource_id=saved.id; insert into public.content_revisions(resource_type,resource_id,version,snapshot,event,created_by) values('destination',saved.id,v,jsonb_build_object('content',content_data,'seo',seo_data),'draft_saved',(select auth.uid())); end if; return jsonb_build_object('lockVersion',saved.lock_version,'updatedAt',saved.updated_at); end $$;
create function public.cms_publish_destination(requested_destination_id uuid,expected_lock_version int,content_data jsonb,seo_data jsonb) returns jsonb language plpgsql set search_path='' as $$ declare saved public.content_entries;v int;begin
if not public.current_user_has_permission('content.publish') or not public.current_user_has_permission('seo.publish') then raise exception 'Publishing requires an authorized MFA session.' using errcode='42501';end if;
update public.content_entries set title=content_data->>'name',slug=content_data->>'slug',sort_order=(content_data->>'sortOrder')::int,draft_data=content_data,published_data=content_data,status='published',archived_at=null,published_at=now(),updated_by=(select auth.uid()) where id=requested_destination_id and content_type='destination' and lock_version=expected_lock_version returning * into saved;if saved.id is null then raise exception 'This destination was changed in another session.' using errcode='40001';end if;update public.seo_entries set draft_data=seo_data,published_data=seo_data,published_at=now() where content_entry_id=saved.id;select coalesce(max(version),0)+1 into v from public.content_revisions where resource_type='destination' and resource_id=saved.id;insert into public.content_revisions(resource_type,resource_id,version,snapshot,event,created_by)values('destination',saved.id,v,jsonb_build_object('content',content_data,'seo',seo_data),'published',(select auth.uid()));return jsonb_build_object('lockVersion',saved.lock_version,'updatedAt',saved.updated_at);end $$;
create function public.cms_unpublish_destination(requested_destination_id uuid,expected_lock_version int) returns jsonb language plpgsql set search_path='' as $$ declare saved public.content_entries;v int;s jsonb;begin if not public.current_user_has_permission('content.publish') or not public.current_user_has_permission('seo.publish') then raise exception 'Unpublishing requires an authorized MFA session.' using errcode='42501';end if;update public.content_entries set status='draft',published_data=null,published_at=null,updated_by=(select auth.uid()) where id=requested_destination_id and lock_version=expected_lock_version returning * into saved;if saved.id is null then raise exception 'This destination was changed in another session.' using errcode='40001';end if;update public.seo_entries set published_data=null,published_at=null where content_entry_id=saved.id returning draft_data into s;select coalesce(max(version),0)+1 into v from public.content_revisions where resource_type='destination' and resource_id=saved.id;insert into public.content_revisions(resource_type,resource_id,version,snapshot,event,created_by)values('destination',saved.id,v,jsonb_build_object('content',saved.draft_data,'seo',s),'unpublished',(select auth.uid()));return jsonb_build_object('lockVersion',saved.lock_version,'updatedAt',saved.updated_at);end $$;
create function public.cms_archive_destination(requested_destination_id uuid,expected_lock_version int) returns jsonb language plpgsql set search_path='' as $$ declare saved public.content_entries;v int;s jsonb;begin if not public.current_user_has_permission('content.archive') then raise exception 'You do not have permission to archive destinations.' using errcode='42501';end if;update public.content_entries set status='archived',published_data=null,published_at=null,archived_at=now(),updated_by=(select auth.uid()) where id=requested_destination_id and lock_version=expected_lock_version returning * into saved;if saved.id is null then raise exception 'This destination was changed in another session.' using errcode='40001';end if;update public.seo_entries set published_data=null,published_at=null where content_entry_id=saved.id returning draft_data into s;select coalesce(max(version),0)+1 into v from public.content_revisions where resource_type='destination' and resource_id=saved.id;insert into public.content_revisions(resource_type,resource_id,version,snapshot,event,created_by)values('destination',saved.id,v,jsonb_build_object('content',saved.draft_data,'seo',s),'archived',(select auth.uid()));return jsonb_build_object('lockVersion',saved.lock_version,'updatedAt',saved.updated_at);end $$;
create function public.cms_restore_destination_revision(requested_destination_id uuid,requested_revision_id uuid,expected_lock_version int) returns jsonb language plpgsql set search_path='' as $$ declare saved public.content_entries;snap jsonb;v int;begin if not public.current_user_has_permission('content.edit') or not public.current_user_has_permission('seo.edit') then raise exception 'You do not have permission to restore destination versions.' using errcode='42501';end if;select snapshot into snap from public.content_revisions where id=requested_revision_id and resource_type='destination' and resource_id=requested_destination_id;if snap is null then raise exception 'The selected destination version does not exist.' using errcode='P0002';end if;update public.content_entries set draft_data=snap->'content',updated_by=(select auth.uid()) where id=requested_destination_id and lock_version=expected_lock_version returning * into saved;if saved.id is null then raise exception 'This destination was changed in another session.' using errcode='40001';end if;update public.seo_entries set draft_data=snap->'seo' where content_entry_id=saved.id;select coalesce(max(version),0)+1 into v from public.content_revisions where resource_type='destination' and resource_id=saved.id;insert into public.content_revisions(resource_type,resource_id,version,snapshot,event,created_by)values('destination',saved.id,v,snap,'restored',(select auth.uid()));return jsonb_build_object('lockVersion',saved.lock_version,'updatedAt',saved.updated_at,'content',snap->'content','seo',snap->'seo');end $$;
revoke all on function public.cms_create_destination(text,text,text,jsonb,jsonb),public.cms_save_destination_draft(uuid,int,jsonb,jsonb,boolean),public.cms_publish_destination(uuid,int,jsonb,jsonb),public.cms_unpublish_destination(uuid,int),public.cms_archive_destination(uuid,int),public.cms_restore_destination_revision(uuid,uuid,int) from public;
grant execute on function public.cms_create_destination(text,text,text,jsonb,jsonb),public.cms_save_destination_draft(uuid,int,jsonb,jsonb,boolean),public.cms_publish_destination(uuid,int,jsonb,jsonb),public.cms_unpublish_destination(uuid,int),public.cms_archive_destination(uuid,int),public.cms_restore_destination_revision(uuid,uuid,int) to authenticated;
